import {
  BaseGatewayAdapter,
  type GatewayMetadata,
  type GatewayField,
  type InitiateParams,
  type InitiateResult,
  type VerifyResult,
  type Credentials,
  type GatewayContext,
} from '../base';
import { gwJson } from '../kit/http';

const API_URL = "https://api.omise.co";

const SLUG = "truemoney";

export class TruemoneyGateway extends BaseGatewayAdapter {
  metadata(): GatewayMetadata {
    return {
      name: "TrueMoney Wallet",
      slug: "truemoney",
      version: '1.0.0',
      description: "TrueMoney e-wallet integration via Omise hosted sources",
      author: 'EdgePay Gateway Plugin Suite (AGPLv3) — EdgePay port',
      type: 'gateway',
      supported_currencies: ["THB"],
      capabilities: ["verification"],
    };
  }

  fields(): GatewayField[] {
    return [
      { name: "secret_key", label: "Omise Secret Key", type: "password" as const, required: true },
    ];
  }

  async initiate(_params: InitiateParams, _credentials: Credentials, _ctx?: GatewayContext): Promise<InitiateResult> {
    const res = await gwJson({
      url: `${String(API_URL)}/sources`,
      method: 'GET',
      timeoutMs: 15000,
    });
    if (res.data === null) throw new Error(`${SLUG}: invalid response`);
    const d = res.data as Record<string, unknown>;
    const chargeId = String(((d) as Record<string, unknown>)["id"] ?? '');
    const scannableCode = ((d) as Record<string, unknown>)["scannable_code"] ?? {};
    const image = ((scannableCode) as Record<string, unknown>)["image"] ?? {};
    const downloadUri = String(((image) as Record<string, unknown>)["download_uri"] ?? '');
    const redirectUrl = String((((d) as Record<string, unknown>)["authorize_uri"] ?? downloadUri) ?? '');
    return {
          redirect_url: (redirectUrl || undefined) as string | undefined,
          session_id: (chargeId || undefined) as string | undefined,
        };
  }

  async verify(callbackData: Record<string, unknown>, credentials: Credentials, _ctx?: GatewayContext): Promise<VerifyResult> {
    const cb = callbackData as Record<string, unknown>;
    if (String(cb["charge_id"] ?? '') === '') {
      return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
    }
    const secretKey = String(credentials["secret_key"] ?? '');
    const res = await gwJson({
      url: `${String(API_URL)}/charges/${String(encodeURIComponent(String(cb["charge_id"] ?? cb["id"])))}`,
      method: 'GET',
      headers: { ["Authorization"]: `Basic ${btoa(`${String(secretKey)}:`)}` },
      timeoutMs: 15000,
    });
    if (res.data === null) {
          return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
        }
    const d = res.data as Record<string, unknown>;
    const ok = String(((d) as Record<string, unknown>)["status"]) === String("successful");
    return {
          success: ok,
          gateway_trx_id: String(""),
          status: (ok ? 'completed' : 'failed') as VerifyResult['status'],
      amount: null,
        };
  }

  async verifyWebhook(_input: { rawBody: string; headers: Record<string, string>; credentials: Credentials }): Promise<boolean> {
    return false;
  }
}
